// Loop over all input items
let results = [];

for (const item of $input.all()) {

  // Grab the raw output from the AI. 
  // ⚠️ CHANGE 'text' to whatever field your AI output is actually stored in!
  // E.g., item.json.message.content (for OpenAI) or item.json.output (for others)
  let rawAiOutput = $input.first().json.content.parts[0].text || "";

  // AIs love to disobey the "no markdown" rule. Let's scrub the backticks and "json" text.
  let cleanedText = rawAiOutput
    .replace(/^```json/mi, '') // Removes ```json at the start
    .replace(/^```/mi, '')     // Removes ``` at the start if it forgot 'json'
    .replace(/```$/mi, '')     // Removes ``` at the end
    .trim();                   // Cleans up any leftover whitespace

  try {
    // Convert the cleaned string into a proper JavaScript Object
    let parsedData = JSON.parse(cleanedText);

    // Pass the parsed object forward as the new item data
    results.push({ json: parsedData });

  } catch (error) {
    // If the AI completely hallucinates and ruins the JSON, catch the error 
    // so the workflow doesn't completely crash and burn.
    results.push({ 
      json: { 
        error: "JSON Parsing Failed!", 
        reason: error.message,
        raw_output: rawAiOutput 
      } 
    });
  }
}

return results;
